solutions.naive:
class Solution:
    def minNumberOperations(self, target: list[int]) -> int:
        arr = target[:]
        ans = 0
        while any(x > 0 for x in arr):
            i = 0
            while i < len(arr):
                if arr[i] == 0:
                    i += 1
                    continue
                ans += 1
                while i < len(arr) and arr[i] > 0:
                    arr[i] -= 1
                    i += 1
        return ans

solutions.better:
class Solution:
    def minNumberOperations(self, target: list[int]) -> int:
        def solve(l: int, r: int, base: int) -> int:
            if l > r:
                return 0
            m = min(target[l:r + 1])
            cost = m - base
            i = l
            while i <= r:
                if target[i] == m:
                    i += 1
                else:
                    j = i
                    while j <= r and target[j] > m:
                        j += 1
                    cost += solve(i, j - 1, m)
                    i = j
            return cost
        return solve(0, len(target) - 1, 0)

